const data = await ctx.call("records", {});
console.log(data);
const best = new Map();
for (const record of data.records) {
  const current = best.get(record.sku);
  if (!current || record.revision > current.revision) best.set(record.sku, record);
}
const ids = [...best.values()].filter(record => record.active).map(record => record.id).sort();
ctx.done({ids});

