for (const record of records) {
  const current = chosen.get(record.sku);
  if (!current || record.revision > current.revision) chosen.set(record.sku, record);
}
ctx.done({
  ids: [...chosen.values()]
    .filter(record => record.active)
    .map(record => record.id)
    .sort()
});

